new file mode 100644
index 0000000000..5ed35a85a6
--- /dev/null
+++ b/src/backends/drm/drm_cec.cpp
@@ -0,0 +1,193 @@
+/*
+    KWin - the KDE window manager
+    This file is part of the KDE project.
+
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+#include "drm_cec.h"
+#include "drm_logging.h"
+#include "utils/filedescriptor.h"
+#include "utils/udev.h"
+
+#include <QFile>
+#include <QSocketNotifier>
+#include <QThreadPool>
+
+#include <cerrno>
+#include <cstring>
+#include <fcntl.h>
+#include <linux/cec-funcs.h>
+#include <linux/cec.h>
+#include <optional>
+#include <sys/ioctl.h>
+#include <sys/sysmacros.h>
+
+namespace KWin
+{
+
+static std::optional<cec_connector_info> connectorInfo(const QString &devNode)
+{
+    FileDescriptor fd(open(QFile::encodeName(devNode).constData(), O_RDWR | O_NONBLOCK | O_CLOEXEC));
+    if (!fd.isValid()) {
+        qCDebug(KWIN_DRM) << "Failed to open" << devNode << strerror(errno);
+        return std::nullopt;
+    }
+    cec_caps caps{};
+    if (ioctl(fd.get(), CEC_ADAP_G_CAPS, &caps) != 0 || !(caps.capabilities & CEC_CAP_CONNECTOR_INFO)) {
+        return std::nullopt;
+    }
+    cec_connector_info info{};
+    if (ioctl(fd.get(), CEC_ADAP_G_CONNECTOR_INFO, &info) != 0 || info.type != CEC_CONNECTOR_TYPE_DRM) {
+        return std::nullopt;
+    }
+    return info;
+}
+
+static uint8_t existingLogicalAddress(int fd)
+{
+    cec_log_addrs addrs{};
+    if (ioctl(fd, CEC_ADAP_G_LOG_ADDRS, &addrs) == 0 && addrs.num_log_addrs > 0) {
+        return addrs.log_addr[0];
+    }
+    return CEC_LOG_ADDR_INVALID;
+}
+
+static std::optional<uint8_t> claimLogicalAddress(int fd)
+{
+    cec_caps caps{};
+    if (ioctl(fd, CEC_ADAP_G_CAPS, &caps) != 0 || !(caps.capabilities & CEC_CAP_LOG_ADDRS)) {
+        return std::nullopt;
+    }
+    cec_log_addrs addrs{
+        .cec_version = CEC_OP_CEC_VERSION_1_4,
+        .num_log_addrs = 1,
+        .vendor_id = CEC_VENDOR_ID_NONE,
+    };
+    std::strncpy(addrs.osd_name, "KDE Plasma", sizeof(addrs.osd_name) - 1);
+    addrs.primary_device_type[0] = CEC_OP_PRIM_DEVTYPE_PLAYBACK;
+    addrs.log_addr_type[0] = CEC_LOG_ADDR_TYPE_PLAYBACK;
+    addrs.all_device_types[0] = CEC_OP_ALL_DEVTYPE_PLAYBACK;
+    if (ioctl(fd, CEC_ADAP_S_LOG_ADDRS, &addrs) != 0) {
+        qCDebug(KWIN_DRM) << "Failed to claim a CEC logical address" << strerror(errno);
+        return std::nullopt;
+    }
+    return addrs.log_addr[0];
+}
+
+static void releaseLogicalAddress(int fd)
+{
+    cec_log_addrs addrs{};
+    if (ioctl(fd, CEC_ADAP_S_LOG_ADDRS, &addrs) != 0) {
+        qCDebug(KWIN_DRM) << "Failed to release the CEC logical address" << strerror(errno);
+    }
+}
+
+DrmCecAdapters::DrmCecAdapters(Udev *udev)
+    : m_monitor(udev->createMonitor())
+{
+    if (m_monitor) {
+        m_monitor->filterSubsystemDevType("cec");
+        const int fd = m_monitor->fd();
+        if (fd != -1) {
+            m_notifier = std::make_unique<QSocketNotifier>(fd, QSocketNotifier::Read);
+            connect(m_notifier.get(), &QSocketNotifier::activated, this, &DrmCecAdapters::handleUdevEvent);
+            m_monitor->enable();
+        }
+    }
+    const auto devices = udev->listCecAdapters();
+    for (const auto &device : devices) {
+        add(device->devNode());
+    }
+}
+
+DrmCecAdapters::~DrmCecAdapters() = default;
+
+bool DrmCecAdapters::add(const QString &devNode)
+{
+    const std::optional<cec_connector_info> info = connectorInfo(devNode);
+    if (!info) {
+        return m_adapters.remove(devNode);
+    }
+    m_adapters[devNode] = Connector{
+        .cardNumber = info->drm.card_no,
+        .connectorId = info->drm.connector_id,
+    };
+    return true;
+}
+
+void DrmCecAdapters::handleUdevEvent()
+{
+    bool changed = false;
+    while (auto device = m_monitor->getDevice()) {
+        const QString devNode = device->devNode();
+        if (devNode.isEmpty()) {
+            continue;
+        }
+        if (device->action() == QLatin1StringView("add")) {
+            changed |= add(devNode);
+        } else if (device->action() == QLatin1StringView("remove")) {
+            changed |= m_adapters.remove(devNode);
+        }
+    }
+    if (changed) {
+        Q_EMIT adaptersChanged();
+    }
+}
+
+QString DrmCecAdapters::adapter(dev_t drmDevice, uint32_t connectorId) const
+{
+    for (auto it = m_adapters.cbegin(); it != m_adapters.cend(); ++it) {
+        if (it->cardNumber == minor(drmDevice) && it->connectorId == connectorId) {
+            return it.key();
+        }
+    }
+    return QString();
+}
+
+void DrmCecAdapters::oneTouchPlay(const QString &adapter)
+{
+    // talking to the adapter blocks until the messages are acknowledged
+    QThreadPool::globalInstance()->start([adapter]() {
+        const FileDescriptor fd(open(QFile::encodeName(adapter).constData(), O_RDWR | O_CLOEXEC));
+        if (!fd.isValid()) {
+            qCDebug(KWIN_DRM) << "Failed to open" << adapter << strerror(errno);
+            return;
+        }
+        uint16_t physicalAddress = CEC_PHYS_ADDR_INVALID;
+        if (ioctl(fd.get(), CEC_ADAP_G_PHYS_ADDR, &physicalAddress) != 0 || physicalAddress == CEC_PHYS_ADDR_INVALID) {
+            return;
+        }
+        // use the address another program (cec-ctl, libcec...) configured, and
+        // don't leave one we claimed ourselves behind on the adapter
+        uint8_t logicalAddress = existingLogicalAddress(fd.get());
+        bool claimed = false;
+        if (logicalAddress == CEC_LOG_ADDR_INVALID) {
+            const std::optional<uint8_t> claimedAddress = claimLogicalAddress(fd.get());
+            claimed = claimedAddress.has_value();
+            logicalAddress = claimedAddress.value_or(CEC_LOG_ADDR_INVALID);
+        }
+        if (logicalAddress == CEC_LOG_ADDR_INVALID) {
+            logicalAddress = CEC_LOG_ADDR_UNREGISTERED;
+        }
+
+        cec_msg msg;
+        cec_msg_init(&msg, logicalAddress, CEC_LOG_ADDR_TV);
+        cec_msg_image_view_on(&msg);
+        if (ioctl(fd.get(), CEC_TRANSMIT, &msg) != 0 || !(msg.tx_status & CEC_TX_STATUS_OK)) {
+            qCDebug(KWIN_DRM) << "Failed to send CEC Image View On" << strerror(errno) << msg.tx_status;
+        } else if (logicalAddress != CEC_LOG_ADDR_UNREGISTERED) {
+            cec_msg_init(&msg, logicalAddress, CEC_LOG_ADDR_BROADCAST);
+            cec_msg_active_source(&msg, physicalAddress);
+            if (ioctl(fd.get(), CEC_TRANSMIT, &msg) != 0 || !(msg.tx_status & CEC_TX_STATUS_OK)) {
+                qCDebug(KWIN_DRM) << "Failed to send CEC Active Source" << strerror(errno) << msg.tx_status;
+            }
+        }
+        if (claimed) {
+            releaseLogicalAddress(fd.get());
+        }
+    });
+}
+
+}
