+/**
+ * Keeps track of the HDMI-CEC adapters that belong to DRM connectors.
+ */
+class DrmCecAdapters : public QObject
+{
+    Q_OBJECT
+
+public:
+    explicit DrmCecAdapters(Udev *udev);
+    ~DrmCecAdapters() override;
+
+    /**
+     * @returns the device node of the HDMI-CEC adapter of the given connector,
+     * or an empty string if it has none we can access
+     */
+    QString adapter(dev_t drmDevice, uint32_t connectorId) const;
+
+    /**
+     * Asks the HDMI-CEC device on the given adapter, usually a TV, to turn on
+     * and switch to our input ("One Touch Play"). This happens asynchronously.
+     */
+    static void oneTouchPlay(const QString &adapter);
+
+Q_SIGNALS:
+    void adaptersChanged();
+
+private:
+    void handleUdevEvent();
+    bool add(const QString &devNode);
+
+    struct Connector
+    {
+        uint32_t cardNumber;
+        uint32_t connectorId;
+    };
+    std::unique_ptr<UdevMonitor> m_monitor;
+    std::unique_ptr<QSocketNotifier> m_notifier;
+    QHash<QString, Connector> m_adapters;
+};
+
+}
